SPEC = json.load(open(os.path.join(HERE, "spec.json"), encoding="utf-8"))
EVID = re.compile(r"^\s*(.+?):(\d+)(?:\s*-\s*(\d+))?\s*$")


def finish(score, msg=""):
    if msg:
        print(msg)
    print(json.dumps({"score": max(0.0, min(1.0, score))}))
    sys.exit(0)


