    s = s.strip()
    s = re.sub(r"\(.*$", "", s)
    s = re.split(r"::|#|\.", s)[-1] if re.search(r"[A-Za-z_]", s) else s
    return s.strip().lower()


def norm_text(s):
    return re.sub(r"[\s`'\"]+", " ", s.strip().lower())


